1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	const BLOCK_SIZE = 3;
69	const BLOCK_BASE_PREMIUM = 60;
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
72	const HIGH_ENCHANTMENT_THRESHOLD = 5;
73	
74	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
75	
76	/** Rounds to whole G in the MHPCO's favour. */
77	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
78	
79	const groupByType = (items: Item[]): Map<string, Item[]> => {
80	  const groups = new Map<string, Item[]>();
81	  for (const item of items) {
82	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
83	  }
84	  return groups;
85	};
86	
87	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
88	
89	/**
90	 * Components are priced per group of alike items, because a building block of
91	 * exactly 3 alike components earns a special rate. Main items price per item.
92	 */
93	const basePremiumForGroup = (type: string, group: Item[]): number => {
94	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
95	    return BLOCK_BASE_PREMIUM;
96	  }
97	  return sum(group.map(basePremiumForItem));
98	};
99	
100	/** Item-specific surcharges apply to the affected item's own base premium. */
101	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
102	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
103	  {
104	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
105	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
106	  },
107	];
108	
109	const itemSurchargeTotalFor = (item: Item): number =>
110	  sum(
111	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
112	      ({ rate }) => basePremiumForItem(item) * rate,
113	    ),
114	  );
115	
116	const quotePremium = (items: Item[]): number => {
117	  const policyBasePremium = sum(
118	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
119	  );
120	  const itemSurchargeTotal = sum(items.map(itemSurchargeTotalFor));
121	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
122	  return roundUpToWholeG(
123	    policyBasePremium + itemSurchargeTotal + initialAssessmentSurcharge + PROCESSING_FEE,
124	  );
125	};
126	
127	export const runScenario = (scenario: Scenario): ScenarioResult => {
128	  return {
129	    results: scenario.steps.map((step) => ({
130	      premium: quotePremium((step as QuoteStep).items),
131	    })),
132	  };
133	};
