4	describe("MHPCO Claim Office", () => {
5	  describe("quote — base premiums", () => {
6	    it("empty item list → premium 5 G (only the processing fee)", () => {
7	      const scenario: Scenario = {
8	        customer: { yearsWithMHPCO: 0 },
9	        steps: [{ op: "quote", items: [] }],
10	      };
11	
12	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	    });
14	    // premium = base + 10 % initial assessment surcharge + 5 G processing fee
15	    it.each([
16	      { type: "sword", base: 100, premium: 115 },
17	      { type: "amulet", base: 60, premium: 71 },
18	      { type: "staff", base: 80, premium: 93 },
19	      { type: "potion", base: 40, premium: 49 },
20	      { type: "rune", base: 25, premium: 33 },
21	      { type: "moonstone", base: 25, premium: 33 },
22	    ])("a single $type → base premium $base G", ({ type, premium }) => {
23	      const scenario: Scenario = {
24	        customer: { yearsWithMHPCO: 0 },
25	        steps: [{ op: "quote", items: [{ type }] }],
26	      };
27	
28	      expect(runScenario(scenario)).toEqual({ results: [{ premium }] });
29	    });
30	  });
31	
32	  describe("quote — building block of 3 alike components", () => {
33	    it("2 runes → 50 G base premium", () => {
34	      const scenario: Scenario = {
35	        customer: { yearsWithMHPCO: 0 },
36	        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
37	      };
38	
39	      // 2 × 25 = 50 base (no block: requires exactly 3)
40	      // 50 + 5 initial assessment = 55, + 5 fee = 60
41	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
42	    });
43	    it("3 runes → 60 G base premium (block applies)", () => {
44	      const scenario: Scenario = {
45	        customer: { yearsWithMHPCO: 0 },
46	        steps: [
47	          { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
48	        ],
49	      };
50	
51	      // block of 3 alike components → 60 base (not 3 × 25 = 75)
52	      // 60 + 6 initial assessment = 66, + 5 fee = 71
53	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
54	    });
55	    it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
56	      const scenario: Scenario = {
57	        customer: { yearsWithMHPCO: 0 },
58	        steps: [{ op: "quote", items: Array.from({ length: 4 }, () => ({ type: "rune" })) }],
59	      };
60	
61	      // 4 × 25 = 100 base (the block does not apply to a subset of 3)
62	      // 100 + 10 initial assessment = 110, + 5 fee = 115
63	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
64	    });
65	    it("7 runes → 175 G base premium", () => {
66	      const scenario: Scenario = {
67	        customer: { yearsWithMHPCO: 0 },
68	        steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
69	      };
70	
71	      // 7 × 25 = 175 base (the block does not repeat: not 2 blocks + 1)
72	      // 175 + 17.5 initial assessment = 192.5, + 5 fee = 197.5 → rounds up to 198
73	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
74	    });
75	    it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
76	      const scenario: Scenario = {
77	        customer: { yearsWithMHPCO: 0 },
78	        steps: [
79	          {
80	            op: "quote",
81	            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
82	          },
83	        ],
84	      };
85	
86	      // Pins "alike" = the SAME TYPE, not the same family: 3 components but
87	      // no block, because the rune group is 2 and the moonstone group is 1.
88	      // 3 × 25 = 75 base; 75 + 7.5 = 82.5, + 5 fee = 87.5 → rounds up to 88
89	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 88 }] });
90	    });
91	    it("3 runes + 3 moonstones → 120 G base premium (two separate blocks)", () => {
92	      const scenario: Scenario = {
93	        customer: { yearsWithMHPCO: 0 },
94	        steps: [
95	          {
96	            op: "quote",
97	            items: [
98	              ...Array.from({ length: 3 }, () => ({ type: "rune" })),
99	              ...Array.from({ length: 3 }, () => ({ type: "moonstone" })),
100	            ],
101	          },
102	        ],
103	      };
104	
105	      // each type forms its own block: 60 + 60 = 120 base
106	      // 120 + 12 initial assessment = 132, + 5 fee = 137
107	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 137 }] });
108	    });
109	  });
110	
111	  describe("quote — item-specific modifiers", () => {
112	    it("cursed sword → 50 % risk surcharge on that item's base premium", () => {
113	      const scenario: Scenario = {
114	        customer: { yearsWithMHPCO: 0 },
115	        steps: [
116	          {
117	            op: "quote",
118	            items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
119	          },
120	        ],
121	      };
122	
123	      // Spec's "Newcomer with a cursed sword" integration example:
124	      // 100 G base + 50 G curse + 10 G first insurance = 160 G + 5 G fee = 165 G
125	      // Note the 10 G is 10 % of the policy BASE premium (100), not of 150 —
126	      // policy-wide modifiers apply to the sum of item base premiums.
