138	      };
139	
140	      // enchantment exactly 5 is the threshold boundary (>= 5), so it applies
141	      // 100 base + 30 high enchantment + 10 initial assessment (10 % of the
142	      // unmodified 100) = 140, + 5 fee = 145
143	      expect(runScenario(scenario)).toEqual({ results: [{ premium: 145 }] });
144	    });
145	    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
146	    it.todo("cursed sword with enchantment 5 → both surcharges apply");
147	  });
148	
149	  describe("quote — policy-wide modifiers", () => {
150	    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
151	    it.todo("customer with 1 year with MHPCO → no loyalty discount");
152	    it.todo("first insurance → 10 % initial assessment surcharge on the policy base premium");
153	    it.todo("the customer's second quote → additional 15 % follow-up contract discount");
154	  });
155	
156	  describe("quote — modifier scope on multi-item policies", () => {
157	    it.todo(
158	      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G; curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
159	    );
160	  });
161	
162	  describe("quote — rounding in the MHPCO's favour", () => {
163	    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
164	    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
165	  });
166	
167	  describe("claim — standard reimbursement", () => {
168	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
169	    it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
170	  });
171	
172	  describe("claim — special clauses", () => {
173	    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause only)");
174	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
175	    it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (50 % clause at the threshold)");
176	    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
177	  });
178	
179	  describe("claim — deductible per damage event", () => {
180	    it.todo(
181	      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible once per damaged item)",
182	    );
183	    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
184	  });
185	
186	  describe("claim — insurance sum and cap", () => {
187	    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
188	    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
189	    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
190	    it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value (premium modifiers do not raise the cap)");
191	    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
192	    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)");
193	  });
194	
195	  describe("claim — multiple items of the same type", () => {
196	    it.todo(
197	      "a policy covers two swords; two sword damage entries → each entry is a separate damage with its own deductible",
198	    );
199	    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
200	  });
201	
202	  describe("errors", () => {
203	    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
204	    it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
205	    it.todo("claim references a damage entry with an unknown item type → error");
