210	    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword (enchantment 3) → premium 165 G");
211	    it.todo("long-standing customer (3 years), second quote, cursed steel sword (enchantment 7) → premium 160 G");
212	  });
213	});
